export function normalizeTranslationKey(text: string): string {
  return text.replace(/\s+/g, " ").trim();
}

export function translateSolutionsText(en: string): string | undefined {
  const key = normalizeTranslationKey(en);
  if (!key) return undefined;
  return SOLUTIONS_AR_TRANSLATIONS[key];
}
